INSERT OR REPLACE INTO content_items (id, channel_id, title, cover_url, cover_version, synopsis, category, is_private, shareable, enabled, first_published_at, created_at, updated_at) VALUES ('anime_modu_16720', 'anime', '灵武大陆', 'https://www.mdzypic.com/upload/vod/20240726-1/1746eea4cd9f3742a9674f17d17e3aae.jpg', 'v1', '灵武大陆，一个灵力和武魂并存的世界，灵修一念动山河，武者徒手撕天地。星辰镇昔日天才辰天，十岁后武魂沉寂、灵海枯竭，自此沦为家族废物，受尽他人冷眼。在一次生死搏斗中，辰天掉下悬崖，误入上古剑帝布置的大阵，在天书力量的作用下觉醒了灵武双修体质，同时还得到一份陌生的记忆和一枚神秘的储物戒指，从此逆境崛起，破天道掌轮回，终渡帝', '玄幻', 0, 1, 1, 1790944623, 1790944623, 1790944623);
