INSERT OR REPLACE INTO content_items (id, channel_id, title, cover_url, cover_version, synopsis, category, is_private, shareable, enabled, first_published_at, created_at, updated_at) VALUES ('anime_modu_90523', 'anime', '转生成为魔剑了第二季', 'https://www.mdzypic.com/upload/vod/20261001-1/10b8348a7e8e14ed6e7001ce31f8fe3e.webp', 'v1', '曾以无名奴隶之身受尽欺凌的黑猫族少女芙兰，与一柄拥有自我意识的剑 ——「师傅」相遇，成为了它的持有者。 加入要塞都市艾蕾萨的冒险者公会后，芙兰接连完成各类委托，以冒险者的身份声名鹊起。 芙兰以抵达力量...', '冒险', 0, 1, 1, 1790944623, 1790944623, 1790944623);
